//! Writing Gespan's part of harness files (CLAUDE.md, AGENTS.md, its own
//! files) without touching the user's text, and keeping files it creates in
//! the tree out of `git status`.

use std::fs;
use std::io::{self, Write};
use std::path::{Component, Path, PathBuf};
use std::sync::atomic::{AtomicU64, Ordering};

pub const BEGIN: &str =
    "<!-- gespan:decisions BEGIN — generated by Gespan, edits here are replaced -->";
pub const END: &str = "<!-- gespan:decisions END -->";

/// A complete marked section: the line indexes of its BEGIN and END lines.
type Span = (usize, usize);

fn is_blank(line: &str) -> bool {
    line.trim_end_matches(['\r', '\n']).is_empty()
}

fn line_body(line: &str) -> &str {
    line.trim_end_matches(['\r', '\n'])
}

/// The line ending the file uses: CRLF when its first line ending is CRLF.
fn line_ending(text: &str) -> &'static str {
    match text.find('\n') {
        Some(i) if text[..i].ends_with('\r') => "\r\n",
        _ => "\n",
    }
}

/// A code fence opener: up to 3 spaces, then 3 or more backticks or tildes
/// (a backtick fence's info string cannot contain a backtick).
fn fence_opener(line: &str) -> Option<(char, usize)> {
    let (ch, run, rest) = fence_run(line)?;
    (run >= 3 && !(ch == '`' && rest.contains('`'))).then_some((ch, run))
}

/// A fence closer: the opener's character, at least as long, nothing after.
fn closes_fence(line: &str, ch: char, len: usize) -> bool {
    fence_run(line).is_some_and(|(c, run, rest)| c == ch && run >= len && rest.trim().is_empty())
}

fn fence_run(line: &str) -> Option<(char, usize, &str)> {
    let body = line_body(line);
    let indent = body.len() - body.trim_start_matches(' ').len();
    if indent > 3 {
        return None;
    }
    let body = &body[indent..];
    let ch = body.chars().next().filter(|c| matches!(c, '`' | '~'))?;
    let run = body.chars().take_while(|&c| c == ch).count();
    Some((ch, run, &body[run..]))
}

/// One pass over the lines. With `fence_aware` set, markers inside code
/// fences are skipped. Also reports whether a fence was still open at the end.
fn scan_sections(lines: &[&str], fence_aware: bool) -> (Vec<Span>, bool) {
    let mut spans = Vec::new();
    let mut open: Option<usize> = None;
    let mut fence: Option<(char, usize)> = None;
    for (i, line) in lines.iter().enumerate() {
        if fence_aware {
            if let Some((ch, len)) = fence {
                if closes_fence(line, ch, len) {
                    fence = None;
                }
                continue;
            }
            if let Some(opener) = fence_opener(line) {
                fence = Some(opener);
                continue;
            }
        }
        let text = line.trim();
        if text == BEGIN {
            open = Some(i);
        } else if text == END {
            if let Some(begin) = open.take() {
                spans.push((begin, i));
            }
        }
    }
    (spans, fence.is_some())
}

/// The sections Gespan treats as its own. A marker counts only as a whole
/// line (ignoring surrounding whitespace); code fences are ``` or ~~~,
/// closed only by the same character at least as long.
///
/// Rule:
/// 1. Fence-aware pass: every BEGIN..END pair outside code fences, where a
///    BEGIN followed by another BEGIN is superseded by the later one. If it
///    finds any, those are the sections.
/// 2. Otherwise, fence-blind pass (markers count even inside fences, which
///    can only be mis-tracked when the file has unbalanced fences): of its
///    pairs, the LAST one whose interior lines, scanned on their own, leave
///    no fence open. Gespan's bodies never contain unbalanced line-leading
///    fences, so a section Gespan wrote always passes this check, while a
///    pair whose interior would open a fence (an orphan BEGIN above a fenced
///    `END`) is rejected.
/// 3. Otherwise there is no section, and Gespan appends one.
///
/// So an orphan BEGIN is user text unless rule 2 pairs it with a later END
/// whose interior is fence-balanced; then the lines between are taken as
/// ours. Accepted trade-off: when a file has no section found by rule 1, a
/// user's fenced example of Gespan's exact markers with a fence-balanced
/// interior (or an orphan BEGIN above a bare END with only balanced text
/// between) is taken as ours and replaced. At most two linear passes over
/// the file plus one over the accepted pair's interior.
fn find_sections(lines: &[&str]) -> Vec<Span> {
    let (spans, _) = scan_sections(lines, true);
    if !spans.is_empty() {
        return spans;
    }
    let (blind, _) = scan_sections(lines, false);
    blind
        .into_iter()
        .rev()
        .find(|&(begin, end)| !scan_sections(&lines[begin + 1..end], true).1)
        .into_iter()
        .collect()
}

/// Replaces Gespan's section in `existing` with `body`, adds it when missing,
/// or removes it when `body` is empty. Everything outside the section is
/// returned byte for byte, with one exception: removing a section also drops
/// the single blank line Gespan put before it. Of several sections the first
/// is kept and the rest are removed; marker lines left behind that would pair
/// up into a new section are dropped on their own, keeping the text between.
/// See `find_sections` for which pairs count as sections.
pub fn replace_section(existing: &str, body: &str) -> String {
    let mut current = replace_section_once(existing, body);
    // Removal is a single pass: repeating it would go on to eat a user's
    // fenced example of the markers once the real section is gone.
    if body.is_empty() {
        return current;
    }
    // Dropping later sections can leave orphan markers that now pair up
    // after the kept section (BEGIN u1 [section] u2 END). Those pairs are not
    // sections Gespan wrote and the lines between them are the user's, so
    // drop only their marker lines, until one section remains; otherwise
    // the next run would find and remove them. Lines before the kept
    // section are untouched, so it stays the first section, and every round
    // removes marker lines, so this ends.
    loop {
        let lines: Vec<&str> = current.split_inclusive('\n').collect();
        let spans = find_sections(&lines);
        if spans.len() <= 1 {
            return current;
        }
        let stray: Vec<usize> = spans[1..].iter().flat_map(|&(b, e)| [b, e]).collect();
        current = lines
            .iter()
            .enumerate()
            .filter(|(i, _)| stray.binary_search(i).is_err())
            .map(|(_, line)| *line)
            .collect();
    }
}

fn replace_section_once(existing: &str, body: &str) -> String {
    let eol = line_ending(existing);
    let lines: Vec<&str> = existing.split_inclusive('\n').collect();
    let spans = find_sections(&lines);
    let render = |terminator: &str| {
        let mut out = String::new();
        out.push_str(BEGIN);
        out.push_str(eol);
        for line in body.lines() {
            out.push_str(line);
            out.push_str(eol);
        }
        out.push_str(END);
        out.push_str(terminator);
        out
    };

    if spans.is_empty() {
        if body.is_empty() {
            return existing.to_owned();
        }
        let mut out = existing.to_owned();
        if !out.is_empty() {
            if !out.ends_with('\n') {
                out.push_str(eol);
            }
            out.push_str(eol);
        }
        out.push_str(&render(eol));
        return out;
    }

    let mut out = String::with_capacity(existing.len() + body.len());
    let mut i = 0;
    for (n, &(begin, end)) in spans.iter().enumerate() {
        let keep_first = n == 0 && !body.is_empty();
        let prev_end = if n == 0 { None } else { Some(spans[n - 1].1) };
        // Lines before this section, minus the blank line that preceded it
        // when the section goes away.
        let mut upto = begin;
        if !keep_first
            && upto > i
            && is_blank(lines[upto - 1])
            && prev_end.is_none_or(|p| upto - 1 > p)
        {
            upto -= 1;
        }
        for line in &lines[i..upto] {
            out.push_str(line);
        }
        if keep_first {
            let terminator = &lines[end][line_body(lines[end]).len()..];
            out.push_str(&render(terminator));
        }
        i = end + 1;
    }
    for line in &lines[i..] {
        out.push_str(line);
    }
    out
}

/// The body of the first section, with line endings normalised to `\n`.
fn section_body(text: &str) -> Option<String> {
    let lines: Vec<&str> = text.split_inclusive('\n').collect();
    let (begin, end) = *find_sections(&lines).first()?;
    Some(
        lines[begin + 1..end]
            .iter()
            .map(|l| line_body(l))
            .collect::<Vec<_>>()
            .join("\n"),
    )
}

/// True when the section now in `existing` differs from the one in
/// `last_written`, i.e. the user edited it. A file with no section has
/// nothing of ours to lose, so it is not "edited".
pub fn user_edited_section(existing: &str, last_written: &str) -> bool {
    match (section_body(existing), section_body(last_written)) {
        (Some(now), Some(then)) => now != then,
        (Some(_), None) => true,
        (None, _) => false,
    }
}

/// Follows a chain of symlinks so a linked file (CLAUDE.md -> AGENTS.md) is
/// updated in place and the link survives. A dangling link resolves to its
/// missing target, which then gets created.
fn resolve_symlinks(path: &Path) -> io::Result<PathBuf> {
    let mut current = path.to_path_buf();
    for _ in 0..40 {
        match fs::symlink_metadata(&current) {
            Ok(meta) if meta.file_type().is_symlink() => {
                let target = fs::read_link(&current)?;
                current = match current.parent() {
                    Some(parent) => parent.join(target),
                    None => target,
                };
            }
            _ => return Ok(current),
        }
    }
    Err(io::Error::other("too many levels of symbolic links"))
}

static TEMP_COUNTER: AtomicU64 = AtomicU64::new(0);

/// Writes `content` to `path` via a temp file in the same directory and a
/// rename, so readers see the old or the new file, never a partial one. The
/// target's permissions are kept (unix); the temp file is removed on any
/// error. Missing parent directories are created, but never for a path
/// reached through a symlink.
///
/// A symlinked `path` is followed (so `CLAUDE.md -> AGENTS.md` keeps its
/// link), but only while the real file's directory is inside `allowed_root`;
/// otherwise nothing is written and `PermissionDenied` is returned. Callers
/// pass the workspace toplevel for project files, the profile home for
/// global ones.
pub fn write_atomic(path: &Path, content: &str, allowed_root: &Path) -> io::Result<()> {
    if path.components().any(|c| c == Component::ParentDir) {
        return Err(io::Error::new(
            io::ErrorKind::PermissionDenied,
            format!("{} contains '..'; not writing", path.display()),
        ));
    }
    let root = fs::canonicalize(allowed_root)?;
    let target = resolve_symlinks(path)?;
    let through_link = target != path;
    let dir = target
        .parent()
        .filter(|p| !p.as_os_str().is_empty())
        .unwrap_or_else(|| Path::new("."))
        .to_path_buf();
    if through_link {
        // Never create directories for a path reached through a link.
        ensure_inside(&fs::canonicalize(&dir)?, &root, path)?;
    } else {
        // Check the nearest existing ancestor before creating anything.
        let existing = dir
            .ancestors()
            .find(|a| a.exists())
            .unwrap_or_else(|| Path::new("."));
        ensure_inside(&fs::canonicalize(existing)?, &root, path)?;
        fs::create_dir_all(&dir)?;
        ensure_inside(&fs::canonicalize(&dir)?, &root, path)?;
    }
    let name = target
        .file_name()
        .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidInput, "path has no file name"))?;
    let unique = format!(
        ".{}.{}.{}.gespan-tmp",
        name.to_string_lossy(),
        std::process::id(),
        TEMP_COUNTER.fetch_add(1, Ordering::Relaxed)
    );
    let tmp = dir.join(unique);
    let result = write_and_rename(&tmp, &target, content, || {
        // The link chain must still lead to the same file, whose directory
        // must still be inside the root.
        if resolve_symlinks(path)? == target {
            ensure_inside(&fs::canonicalize(&dir)?, &root, path)
        } else {
            Err(io::Error::new(
                io::ErrorKind::PermissionDenied,
                format!("{} changed while being written", path.display()),
            ))
        }
    });
    if result.is_err() {
        let _ = fs::remove_file(&tmp);
    }
    result
}

fn ensure_inside(dir: &Path, root: &Path, shown: &Path) -> io::Result<()> {
    if dir.starts_with(root) {
        Ok(())
    } else {
        Err(io::Error::new(
            io::ErrorKind::PermissionDenied,
            format!(
                "{} resolves outside {}; not writing",
                shown.display(),
                root.display()
            ),
        ))
    }
}

fn write_and_rename(
    tmp: &Path,
    path: &Path,
    content: &str,
    recheck: impl FnOnce() -> io::Result<()>,
) -> io::Result<()> {
    let mut file = fs::OpenOptions::new()
        .write(true)
        .create_new(true)
        .open(tmp)?;
    file.write_all(content.as_bytes())?;
    file.flush()?;
    #[cfg(unix)]
    if let Ok(meta) = fs::metadata(path) {
        file.set_permissions(meta.permissions())?;
    }
    file.sync_all()?;
    drop(file);
    recheck()?;
    fs::rename(tmp, path)
}

/// `file` as an anchored exclude pattern (`/dir/name`, '/' separators)
/// relative to the work tree's toplevel; the exclude file's path. `None`
/// outside git, outside the work tree, or inside `.git`.
fn exclude_target(workspace: &Path, file: &Path) -> Option<(String, PathBuf, PathBuf)> {
    let top = crate::git::git_probe(workspace, &["rev-parse", "--show-toplevel"])?;
    let top = fs::canonicalize(top.trim()).ok()?;
    let common = super::scope::git_common_dir(workspace)?;
    let file = canonical_or_parent(file);
    let rel = file.strip_prefix(&top).ok()?;
    let parts: Vec<String> = rel
        .components()
        .map(|c| c.as_os_str().to_string_lossy().into_owned())
        .collect();
    if parts.is_empty() || parts[0] == ".git" {
        return None;
    }
    Some((
        format!("/{}", parts.join("/")),
        common.join("info").join("exclude"),
        common,
    ))
}

/// The file's own path with its directory canonicalised. The file itself is
/// never resolved, so a symlink is excluded under its own name.
fn canonical_or_parent(file: &Path) -> PathBuf {
    match (
        file.parent().and_then(|p| fs::canonicalize(p).ok()),
        file.file_name(),
    ) {
        (Some(parent), Some(name)) => parent.join(name),
        _ => file.to_path_buf(),
    }
}

/// Lists `file` in `<git common dir>/info/exclude` (once), so a file Gespan
/// creates inside the work tree stays out of `git status` without touching
/// `.gitignore`. A no-op outside git or for files outside the work tree.
pub fn ensure_excluded(workspace: &Path, file: &Path) -> io::Result<()> {
    let Some((pattern, exclude, common)) = exclude_target(workspace, file) else {
        return Ok(());
    };
    let current = match fs::read_to_string(&exclude) {
        Ok(text) => text,
        Err(e) if e.kind() == io::ErrorKind::NotFound => String::new(),
        Err(e) => return Err(e),
    };
    if current.lines().any(|l| l.trim_end_matches('\r') == pattern) {
        return Ok(());
    }
    let eol = line_ending(&current);
    let mut next = current;
    if !next.is_empty() && !next.ends_with('\n') {
        next.push_str(eol);
    }
    next.push_str(&pattern);
    next.push_str(eol);
    write_atomic(&exclude, &next, &common)
}

/// Removes exactly the line [`ensure_excluded`] added for `file`.
pub fn remove_excluded(workspace: &Path, file: &Path) -> io::Result<()> {
    let Some((pattern, exclude, common)) = exclude_target(workspace, file) else {
        return Ok(());
    };
    let current = match fs::read_to_string(&exclude) {
        Ok(text) => text,
        Err(e) if e.kind() == io::ErrorKind::NotFound => return Ok(()),
        Err(e) => return Err(e),
    };
    if !current.lines().any(|l| l.trim_end_matches('\r') == pattern) {
        return Ok(());
    }
    let next: String = current
        .split_inclusive('\n')
        .filter(|l| line_body(l) != pattern)
        .collect();
    write_atomic(&exclude, &next, &common)
}
